.segmented-control {
  --sc-label: #6b6a63;
  --sc-track: #ebe8e1;
  --sc-text: #3d3c37;
  --sc-text-muted: #7d7b73;
  --sc-selected-bg: #ffffff;
  --sc-selected-text: #1f1e1a;
  --sc-selected-shadow: 0 1px 2px rgba(31, 30, 26, 0.12), 0 0 0 1px rgba(31, 30, 26, 0.04);
  --sc-hover-bg: rgba(31, 30, 26, 0.05);
  --sc-focus: #3b6fb6;

  display: inline-flex;
  flex-direction: column;
  gap: 0.375rem;
  font-family: inherit;
}

[data-theme="night"] .segmented-control {
  --sc-label: #8b93a7;
  --sc-track: #1d2230;
  --sc-text: #d7dbe6;
  --sc-text-muted: #8b93a7;
  --sc-selected-bg: #343c51;
  --sc-selected-text: #f2f4fa;
  --sc-selected-shadow: 0 1px 2px rgba(0, 0, 0, 0.35), 0 0 0 1px rgba(255, 255, 255, 0.04);
  --sc-hover-bg: rgba(255, 255, 255, 0.05);
  --sc-focus: #8fb4ff;
}

.segmented-control__label {
  font-size: 0.75rem;
  font-weight: 500;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--sc-label);
}

.segmented-control__track {
  display: inline-flex;
  align-items: stretch;
  gap: 2px;
  padding: 3px;
  border-radius: 999px;
  background: var(--sc-track);
}

.segmented-control__option {
  appearance: none;
  border: 0;
  margin: 0;
  padding: 0.5rem 1rem;
  border-radius: 999px;
  background: transparent;
  color: var(--sc-text-muted);
  font: inherit;
  font-size: 0.9375rem;
  line-height: 1.2;
  white-space: nowrap;
  cursor: pointer;
  user-select: none;
  transition:
    background-color 160ms ease,
    color 160ms ease,
    box-shadow 160ms ease;
}

.segmented-control__option:hover:not([aria-checked="true"]) {
  background: var(--sc-hover-bg);
  color: var(--sc-text);
}

.segmented-control__option[aria-checked="true"] {
  background: var(--sc-selected-bg);
  color: var(--sc-selected-text);
  box-shadow: var(--sc-selected-shadow);
  font-weight: 500;
}

.segmented-control__option:focus {
  outline: none;
}

.segmented-control__option:focus-visible {
  outline: 2px solid var(--sc-focus);
  outline-offset: 2px;
}

@media (prefers-reduced-motion: reduce) {
  .segmented-control__option {
    transition: none;
  }
}
